#include <algorithm>
#include <cassert>
#include <cstddef>
#include <iostream>
#include <string>
#include <vector>

void reverse_cstr(char* text) {
    // 호출자는 쓰기 가능한 NUL 종료 배열을 제공합니다. nullptr은 별도로 허용합니다.
    if (text == nullptr) return;
    std::size_t length = 0;
    while (text[length] != '\0') ++length;
    // 끝을 열린 구간으로 잡아 빈 문자열의 length-1 언더플로를 피합니다.
    std::size_t left = 0, right = length;
    while (left < right) {
        --right;
        if (left >= right) break;
        std::swap(text[left], text[right]);
        ++left;
    }
}
int main() {
    // 첫 줄만 읽으며 빈 줄도 유효합니다. ASCII 출력 문자만 허용합니다.
    std::string line;
    if (!std::getline(std::cin, line) || line.size() > 4096) return 1;
    for (unsigned char ch : line) if (ch < 32 || ch > 126) return 1;
    std::vector<char> buffer(line.begin(), line.end());
    buffer.push_back('\0');
    reverse_cstr(buffer.data());
    std::cout << buffer.data() << '\n';
    return std::cout ? 0 : 1;
}
